import sys

def isq(x):
    if x < 2:
        return x
    r = x
    while True:
        nr = (r + x // r) // 2
        if nr >= r:
            return r
        r = nr

data = sys.stdin.read().split()
q = int(data[0])
out = []
for x in data[1:1 + q]:
    out.append(str(isq(int(x) * 10000)))
print('\n'.join(out))

